bool canFinish(int numCourses, const std::vector<std::pair<int,int>>& prerequisites) {
    std::vector<int> inDegree(numCourses, 0);
    std::vector<std::vector<int>> adj(numCourses);
    for (const auto& p : prerequisites) {
        adj[p.second].push_back(p.first);
        inDegree[p.first]++;
    }
    std::queue<int> q;
    for (int i = 0; i < numCourses; ++i) if (inDegree[i] == 0) q.push(i);
    int count = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        count++;
        for (int v : adj[u]) {
            if (--inDegree[v] == 0) q.push(v);
        }
    }
    return count == numCourses;
}

int main() {
    int n, m;
    if (!(std::cin >> n >> m)) return 0;
    std::vector<std::pair<int,int>> prereqs(m);
    for (int i = 0; i < m; ++i) std::cin >> prereqs[i].first >> prereqs[i].second;
    std::cout << (canFinish(n, prereqs) ? 1 : 0) << std::endl;
    return 0;
}

